export function mountAdminCatalog(root,events,onSelect,onDelete){
 const header=document.createElement('div');header.className='section-head';header.innerHTML='<div><h3>กิจกรรมทั้งหมด</h3><p class="sub">เลือกกิจกรรมเพื่อจัดการข้อมูลและการเปิดรับ</p></div>';const search=document.createElement('input');search.className='search';search.placeholder='ค้นหากิจกรรม…';search.setAttribute('aria-label','ค้นหากิจกรรม');header.append(search);root.append(header);
 const list=document.createElement('div');list.className='admin-event-list';root.append(list);const count=document.createElement('p');count.className='sub';count.setAttribute('role','status');root.append(count);
 function draw(){const filtered=events.filter(event=>event.deleted!==true&&String(event.name||'').toLowerCase().includes(search.value.trim().toLowerCase()));list.replaceChildren();count.textContent='พบ '+filtered.length+' กิจกรรม';for(const event of filtered){const row=document.createElement('article');row.className='admin-event-row';const image=document.createElement('div');image.className='admin-event-thumb';image.textContent='KUSK';if(event.posterUrl){try{const url=new URL(event.posterUrl);if(url.protocol==='https:'){const img=document.createElement('img');img.src=url.href;img.alt=event.name;img.loading='lazy';img.onerror=()=>{image.textContent='KUSK'};image.replaceChildren(img)}}catch{}}const info=document.createElement('div');const title=document.createElement('h3');title.textContent=event.name;const date=document.createElement('p');date.className='sub';date.textContent=(event.date||'รอประกาศวันจัด')+' · '+(event.place||'รอระบุสถานที่');const status=document.createElement('p');status.className='sub';status.textContent=(event.registrationOpen?'เปิดรับสมัคร':'ปิดรับสมัคร')+' · '+(event.checkinOpen?'เปิดเช็คอิน':'ปิดเช็คอิน');const seats=document.createElement('p');seats.className='sub';seats.textContent='กันที่นั่ง '+(event.reservedCount||0)+' / '+event.capacity+' คน';info.append(title,date,status,seats);const actions=document.createElement('div');actions.className='admin-event-actions';const button=document.createElement('button');button.className='primary';button.textContent='จัดการกิจกรรม →';button.onclick=()=>onSelect(event.id);actions.append(button);if(onDelete){const remove=document.createElement('button');remove.className='danger-outline';remove.textContent='ลบกิจกรรม';remove.onclick=()=>onDelete(event);actions.append(remove)}row.append(image,info,actions);list.append(row)}}
 search.oninput=draw;draw();
}
